		"story": "【실록 가정내 문서】세타●구 「동생의 치●뽀로 살아난다」 「언젠가 아이가 생기는 것은 아닐까…」 「사라졌으면 좋겠다…」 「하지만 가족이고」 「좋아하지만 싫다」어린 시절부터 성욕이 강한 동생. 나는 재미있어하며 찐친을 만지작거렸던…, 이제는 후회를 하고 있다. 정자를 하루 8번 내게 한 적도 있었다. 거실에서 「가슴을 빨게 해줘」라고 순진한 동생. 점차 몸은 느끼게 되어 버려서, 수유하면서의 손 코키로 목소리를 참을 수 없는 것도. 화장실에서 페라를 조르다. 당연히 마●코도 사용된다, 당연히 중출을 받을 수 있고... 몇번이고 자신의 성기의 정자를 씻어내어 아이가 생기지 않기를 빌었다. 성적인 것을 숨기고 「동생에 대한 푸념」을 친구에게 이야기하고 있는 것을 도둑맞고 말았다. 거기서부터 동생이 바뀌어 버렸다. 폭력은 휘두르지 않지만, 나에 대한 집착심이 폭주해 버렸다. 몇 번이고 당신이 너무 좋아요라고 말해도, 성적으로 위로해도 동생은 만족하지 않는다. 동생은, 그 불안을 자신이 다니는 시설의 중년에게 말해 버린 것 같다. 「가족끼리 섹스」하고 있는 것을 이유로, 나는 협박당해 신체를 빼앗기고 말았다. 중년들의 섹스는 동생 섹스에 비해 공손하고 기분이 좋았다. 제가 중년의 손에서 느끼니까 동생이 슬픈 표정을. 남동생의 섹스는 그날부터 능숙해지고 격렬해졌습니다. 이제 돌이킬 수 없어, 매일매일, 나는 계속해서 오징어를 당하고 동생을 나로부터 받아 버리게 되었다. 「동생은 좋기만 하고 싫다」라고 말하면서도…동생의 물건을 좋아하게 되어 버렸다. 첫회 무료체험 포인트 선물 중! 특집 : 종합 AV 그룹 [망상족] 추천은 이거야!",
