		"story": "좀 더 빨리, 솔직해졌더라면 누구도 상처받지 않고 끝났을 텐데… 나와, 아이카(언니), 리사(여동생)는 소꿉친구로 학창시절에도 계속 함께 있었던 사랑을 좋아했다 그리고, 나를 좋아한다고 확신하고 있었지만, 사이가 너무 좋아서 질질 진전되지 않은 채로 아라서가 되어 버린 자매와 함께 사는 쉐어 하우스에 나는 자주 방해하고 있던 사랑과 둘이서 이야기하고 있었을 때의 일이다 학창시절의 이야기를 떠올리고 있으면 「과거의 영광에 매달려 있기 때문에 여자친구 할 수 없는 거야, 좋은 나이에」라고, 그런 말을 듣지 않으면 안 돼… 화가 나서 대꾸해 버렸다 「남자친구 없는 것은 똑같지! 그런 성격이기 때문에 혼자야」싸움을 짐작하거나 사뭇 위로해 주고, 리사에게 고백받아 사귀기로 했다…아이카에의 분풀이의 생각으로 우리가 사귀게 되었다고 듣자마자 아이카가 노브라 가슴 유혹해 오게 된 가슴 큰 줄은 생각하고 있었지만 이렇게 컸는지… 젖꼭지 보여... '리사는 남자 경험이 없어서 상처받지 않았으면 좋겠어 나로 섹스의 연습하자?」질투한 사랑은 나를 필사적으로 되돌리려고 하거나 하는 것이 가까이에 있는데, 최저인 나는 아이카의 유혹에 넘어가서 몇번이나 관계를 가진 「정말로, 리사를 좋아해?」 「…아이카를 계속 좋아했어」 때문에, 더 빨리, 이 말을 할 수 없었던 것일까…리사에게는 솔직한 마음을 전했다 「그럴 줄 알았어…처음부터 솔직해졌으면 좋았잖아」라고 화내고 나가 버렸지만, 이해해 준 맑고, 연인이 된 우리들은…",
