		"title": "SY-219 — 사랑하는 4.5다다미방의 아내 유이카 씨, 24세 ●아마추어 4.5다다미방 날것 크림파이 시리즈 오노사카 유이카",
		"story": "창문 너머로 간다 강이 보인다. 허름한 4.5다다미방에서, 한 기혼 여성은 쾌락과 사랑을 발견한다. 학기말이 다가오고, 늘어난 야근 때문에 녹초가 된 나는, 힘들어하는 나를 보고 안절부절못하는 동료의 추천으로 한 카이로프랙틱 병원을 소개받았다. 퇴근 후, 부부가 운영하는 작은 병원이었다. 다행히도, 남편이 아닌 아내가 병원을 운영하고 있었다. 그녀는 글래머러스한 몸매에 츠치야 요시오를 닮은 아름다운 얼굴을 가졌는데, 이런 곳에서 일하는 게 안타까울 정도로 아름다웠다. 게다가 실력도 뛰어났다. 그녀는 내 혈자리에 정확한 압력을 가했고, 그 느낌은 마치 해방되는 듯했다. 쾌락에 절정에 다다르려는 순간, 카이로프랙터의 아내가 갑자기 물었다. \"저 기억하세요?\" 순간, 나는 깜짝 놀라 며칠 전 바람을 피웠던 아내인 줄 알았다. 하지만 그녀의 얼굴은 완전히 달랐다. 저렇게 아름다운 사람은 한 번 보면 절대 잊을 수 없다. 그때 아내가 더 가까이 다가왔다. \"아!\" 나는 기억해냈다. 12년 전 내가 담임이었을 때 반장이었던 오노자카였다. 그렇게 성실하고 남들에게 친절했던 오노자카가 이런 병원에서 일하고 있을 거라고는 상상도 못 했다… 게다가 결혼까지 했다니. 이상하게도 오랜만에 재회했는데도 기쁘지 않았다. 이제 내 아내가 된 그녀는 내 건강하지 못한 생활을 걱정하며 밥을 해 주겠다고 했다. 그녀의 친절함은 조금도 변하지 않았다. 그리고… 그녀가 실제로 우리 집에 찾아왔다. 그녀는 병원에서 입었던 흰 가운과는 전혀 다른 꽃무늬 드레스를 입고 있었다. 나는 그녀를 예전 제자가 아닌, 어엿한 한 여성으로 바라보았다. 그녀를 내 방으로 맞이했을 때, 달콤하고 은은한 향기가 코끝을 간지럽혔다. 그것만으로도 내 마음은 금세 흔들렸다. 그녀가 음식을 준비하는 모습을 보며 나는 흥분했고, 마치 댐이 무너지듯 그녀를 껴안고 격렬하게 입술을 사로잡았다. 나는 스스로를 제어할 수 없었다. 옷 위로 그녀의 풍만한 가슴과 엉덩이를 주무르고, 치마를 들어 올려 매끈한 허벅지를 드러내 어루만졌다. 당연히 그녀는 나를 거부하며 그 행위를 부인했다. 하지만 나는 개의치 않고 그녀의 옷을 벗기고 예전 제자의 관능적인 몸을 마구 유린하기 시작했다. 그녀의 아름다운 유두는 매우 예민했고, 내가 거칠게 만질 때마다 그녀의 몸은 살짝 떨렸다. 그녀의 질은 애액으로 가득 차 있었고, 나는 그녀가 나를 받아들이고 싶어 하는 욕망에 응답하듯 삽입했다. 그녀의 질 주름이 마치 마사지를 받는 것처럼 내 성기를 자극했다. 나는 쾌락에 완전히 빠져 젊은 아내를 열정적으로 탐닉했다. 그리고… 질투심으로 가득 찬 우윳빛 액체를 예전 제자이자 이제는 결혼한 여자의 질 깊숙이 사정했다. 그 순간, 믿을 수 없을 만큼 쾌락에 찬 눈물이 뺨을 타고 흘러내렸다… 하지만 그런 일이 있은 후에도 그녀는 여전히 나에게 오믈렛을 만들어 주었다. 정말 고마웠고… 맛있었다. 이것 또한 사랑인가 보다.",
