		"story": "아침. 눈을 뜨니 옆에는 아르바이트 후배 나나가 서 있었다. 둘 다 연인이 있긴 했지만, 어젯밤에 같이 술을 마시고 바람을 피웠다니… 아니, 전혀 기억이 안 난다. 하지만 어제 섹스했던 흔적, 무방비한 잠든 얼굴, 살짝 비치는 젖꼭지, 부드러운 엉덩이, 팬티 위로 드러난 풍만한 보지 라인… 아, 나나 짱 너무 야해. 벌써 많이 했지만 또 하고 싶어. 참을 수 없어 아침 좆물을 쑤셔넣었다! 방금 잠에서 깬 나나가 너무 귀여워서 한 번, 두 번, 세 번이나 사정했다… \"선배… 오늘 아침부터 사정해서 미칠 것 같아!!\" 상관없지만 피스톤으로 나나의 부위를 자극하자, 나나는 쿵쾅거리는 카우걸 자세로 반응하며 몸을 움찔거렸다! \"더는 못 참겠어! 이렇게 많이 한 적은 처음이야!... 아, 사정한다...!!\" 데이트 시간이 되어도 주말 저녁까지 계속 그랬다.",
