		"story": "의붓딸의 첫사랑이 자기일 줄은 꿈에도 생각 못 했어... 늘 엄마와 함께 살며 남자를 만난 적 없는 순진한 소녀였지. 이성과의 접촉이 전혀 없었던 그녀에게 새아빠와의 삶은 모든 게 '자극적'이었어. 그러다 중년 남성에게 반해버렸고, 엄마가 떠나자 팬티도 브라도 없이 버릇없이 굴기 시작했어... \"나짱, 아빠가 갖고 싶었어! 정말 행복해!\" \"오늘부터 이렇게 큰 집에서 살 수 있다니!? 정말 대단해!\" \"아빠는 정말 친절하고 멋지셔... 아빠, 정말 사랑해.\" \"하지만 나짱, 아빠를 사랑하잖아. 사랑하는 사람들은 나쁜 짓도 하지?\" \"너도 나짱을 사랑하잖아?\" 아주 귀여운 얼굴에 브라도 안 입고 젖꼭지도 보이고, 팬티도 안 입고 음모까지 드러난 나짱은 나를 꼭 껴안고 버릇없이 굴면서 새아빠가 누군지도 모르는 거야? 키스 많이 해 줄게. 그리고 네 가냘픈 몸이 새아빠의 큰 배에 파묻힐 만큼 깊이 삽입할게. 나찬도 의붓딸에게 안겨서 놓지 않아서 자궁에 키스 많이 했어. 사정도 많이 했고, 제일 깊은 곳까지 사정도 많이 했지. 나찬의 보지는 너무 꽉 조여 있어서 최고야. 의붓딸의 구애에 푹 빠져서, 몇 번이고 사정하고 또 사정하고, 또 몇 번이고 질내사정하며 음란한 섹스를 했지. 나찬, 나찬. 오늘도 너무 귀여워.",
