		"story": "나츠는 상사와 출장 중이었다. 갑작스러운 폭우에 휩싸인 그녀는 술자리에서 만취한 채 호텔로 돌아왔다. 흠뻑 젖은 그녀의 모습을 본 상사는 그녀를 덮치려 했다. 그녀는 당연히 거부했어야 했지만… 정신을 차려보니 두 사람은 격렬하게 관계를 맺고 있었고, 땀과 침이 뒤섞였다. 그의 움직임 하나하나에 그녀는 경련하며 오르가즘을 느꼈다. 남자친구가 집에서 기다리고 있었지만, 그녀가 혐오하는 남자의 성기가 바로 그녀가 원하던 것이었다. 그녀는 그의 성기를 입속 깊숙이 넣고 뿌리까지 빨아댔다. 길고 가느다란 팔다리를 비틀며 그의 성기를 꽉 붙잡고 더 많은 것을 갈망했다. 짐승처럼 허리를 흔들며 질을 꽉 조였다… 그가 진한 정액을 그녀 안에 쏟아낸 후에도 그녀는 여전히 더 원했다. 두 사람은 이성을 잃고 순수한 본능에 이끌려 서로를 탐닉했다. 격렬하고 열정적인 섹스는 아침까지 계속되었다.",
