		"story": "방과 후, 소꿉친구이자 여자친구인 준은 자연스럽게 아이자와의 방으로 찾아온다. 그런데 오늘따라 아이자와는 평소와 달리 불안해 보인다. 이유를 묻자, 여자친구가 생겼다는 충격적인 소식을 전한다. 흥분을 감추려던 준은 일방적으로 \"여자친구가 널 떠나지 않게 섹스하는 법을 가르쳐줄게\"라며 수업을 시작한다. 처음에는 신체 접촉 없이, 오로지 눈맞춤만 한다. 60초 동안 눈맞춤을 하고, 허리에 손을 얹고… 이러한 동작들이 반복될수록 점차 수위가 올라가 마침내 삽입에 이른다! 하지만 준의 허락 없이는 절대 사정할 수 없다! 여주인공의 소유욕이 드러난 이 수업은 약해진 아이자와의 관계를 단단하게 만들어준다!",
