		"series": "보잘것없는 고추를 구해달라고!? 어릴 적부터 늘 내 방에 드나들던 친구야. 드디어 여자친구가 생긴 나에게 여자들에게 인기 많아지고 섹스하는 법을 제대로 가르쳐주기로 했지. 그녀의 교활하고 음탕한 스타일의 가르침을 하나씩 완수할 때마다 보너스를 받게 되고, 마지막 시험은 질내 사정을 포함한 진짜 화끈한 섹스 수업이야!",
